<template><view class="page"><view class="head row"><view><text class="eyebrow">绿色权益</text><text class="title">积分商城</text></view><view class="wallet">{{points}} 积分</view></view><view v-if="list.length" class="product-grid"><view v-for="item in list" :key="item._id" class="product card" @tap="open(item)"><image v-if="item.image" class="product-image" :src="item.image" mode="aspectFill"/><view v-else class="product-icon">◇</view><text class="product-name">{{item.name}}</text><text class="muted">{{item.carbonLabel||item.description}}</text><text class="carbon">预计减碳 {{item.carbonReduction||0}} kg CO₂/件</text><view class="row price"><text>{{item.points}} 积分</text><text class="stock">库存 {{item.stock}}</text></view></view></view><view v-else class="empty card">暂无上架商品</view><BottomNav active="mall"/></view></template>
<script>import BottomNav from '../../components/BottomNav.vue';import {callCloud} from '../../common/cloud.js';export default{components:{BottomNav},data(){return{list:[],points:0}},async onShow(){this.points=Number(uni.getStorageSync('user_points')||0);try{const result=await callCloud('product-list');this.list=result.data||[]}catch(error){this.list=[]}},methods:{open(item){uni.navigateTo({url:'/pages/personal/product-detail?id='+item._id})}}}</script>
<style lang="scss">@import '../../common/portal.scss';.wallet{padding:16rpx 22rpx;border-radius:30rpx;background:#d6e6e3;color:#006d37;font-size:28rpx}.product-grid{display:grid;grid-template-columns:1fr 1fr;gap:20rpx;margin-top:24rpx}.product{padding:22rpx}.product-image,.product-icon{display:flex;align-items:center;justify-content:center;width:100%;height:180rpx;margin-bottom:18rpx;border-radius:20rpx;background:#d6e6e3;color:#006d37;font-size:70rpx}.product-name{display:block;font-size:27rpx;font-weight:700}.product .muted,.carbon{display:block;margin-top:8rpx;font-size:20rpx}.carbon{color:#347c55}.price{margin-top:14rpx;color:#006d37;font-weight:700}.stock{color:#9aa69f;font-size:20rpx;font-weight:400}.empty{text-align:center}</style>
